def transform(grid):
    bottom = max(r for r, row in enumerate(grid) if any(row))
    out = [[0] * len(grid[0]) for _ in grid]
    for r, row in enumerate(grid):
        shift = bottom - r
        for c, value in enumerate(row):
            nc = c - shift
            if value and nc >= 0:
                out[r][nc] = value
    return out
